runtime.inlineScript:
$raw = [Console]::In.ReadToEnd()
$req = if ($raw) { $raw | ConvertFrom-Json } else { $null }
$lines = @()
$paths = @()
$badge = $null
try {
  $rh = [Runtime.InteropServices.Marshal]::GetActiveObject('Rhino.Application')
  $rs = $rh.GetScriptObject()
  if ($null -ne $rs) {
    $docName = [string]$rs.DocumentName()
    $docPath = [string]$rs.DocumentPath()
    if ($docName) { $badge = $docName; $lines += "rhino_doc: $docName" }
    if ($docPath -and $docName) { $full = Join-Path $docPath $docName; if (Test-Path $full) { $paths += $full } }
    $sel = $rs.SelectedObjects()
    if ($null -ne $sel) { $lines += "rhino_selected_count: $($sel.Count)" }
  }
} catch {
  if ($req -and $req.windowTitle) { $lines += "rhino_window: $($req.windowTitle)" }
}
@{ ok = $true; badge = $badge; lines = $lines; paths = $paths } | ConvertTo-Json -Compress
